<script>
    function showToast(message) {
      const toast = document.getElementById('toastNotification');
      const text = document.getElementById('toastMessage');
      text.innerText = message;
      toast.classList.remove('-translate-y-12', 'opacity-0');
      toast.classList.add('translate-y-0', 'opacity-100');
      setTimeout(() => {
        toast.classList.remove('translate-y-0', 'opacity-100');
        toast.classList.add('-translate-y-12', 'opacity-0');
      }, 2400);
    }

    function toggleWishlist(btn, productName) {
      const icon = btn.querySelector('.material-symbols-outlined');
      const isFilled = icon.innerText === 'favorite';
      if (isFilled) {
        icon.innerText = 'favorite_border';
        btn.classList.remove('text-primary');
        btn.classList.add('text-charcoal-muted');
        showToast('Removed ' + productName);
      } else {
        icon.innerText = 'favorite';
        icon.style.fontVariationSettings = "'FILL' 1";
        btn.classList.remove('text-charcoal-muted');
        btn.classList.add('text-primary');
        showToast('Saved ' + productName + ' to Wishlist');
      }
    }

    function addToCart(productName) {
      showToast('Added ' + productName + ' to Cart');
    }

    function handleNewsletter(e) {
      e.preventDefault();
      const input = document.getElementById('emailInput');
      if (input && input.value) {
        showToast('Welcome to Chummy VIP Club!');
        input.value = '';
      }
    }
  </script>
</div></main><nav class="fixed bottom-0 w-full z-50 pb-safe bg-surface/90 backdrop-blur-xl shadow-[0_-2px_12px_rgba(43,38,37,0.06)]" data-active-classes="text-primary font-label-md"><div class="flex justify-around items-center h-16 px-2"><a aria-current="page" class="flex flex-col items-center justify-center min-w-[64px] h-12 transition-colors gap-1 text-primary font-label-md" data-path="home" href="#"><span class="material-symbols-outlined text-[22px]">home</span><span class="font-label-md text-label-md">Home</span></a><a class="flex flex-col items-center justify-center min-w-[64px] h-12 text-on-surface-variant hover:text-on-surface transition-colors gap-1" data-path="collections" href="#"><span class="material-symbols-outlined text-[22px]">grid_view</span><span class="font-label-md text-label-md">Collections</span></a><a class="flex flex-col items-center justify-center min-w-[64px] h-12 text-on-surface-variant hover:text-on-surface transition-colors gap-1" data-path="wishlist" href="#"><span class="material-symbols-outlined text-[22px]">favorite_border</span><span class="font-label-md text-label-md">Wishlist</span></a><a class="flex flex-col items-center justify-center min-w-[64px] h-12 text-on-surface-variant hover:text-on-surface transition-colors gap-1" data-path="account" href="#"><span class="material-symbols-outlined text-[22px]">person</span><span class="font-label-md text-label-md">Account</span></a></div></nav></body></html>